import{_ as d,C as n,o as c,c as l,j as t,a as o,E as s,a2 as i}from"./chunks/framework.TaNiW7i8.js";const w=JSON.parse('{"title":"Archive a session","description":"","frontmatter":{"title":"Archive a session"},"headers":[],"relativePath":"en/agent/archiver.md","filePath":"en/agent/archiver.md"}'),m={name:"en/agent/archiver.md"};function u(g,e,p,f,v,y){const r=n("AskExample"),a=n("Ask"),h=n("Capture");return c(),l("div",null,[e[0]||(e[0]=t("h1",{id:"archive-a-session",tabindex:"-1"},[o("Archive a session "),t("a",{class:"header-anchor",href:"#archive-a-session","aria-label":'Permalink to "Archive a session"'},"​")],-1)),e[1]||(e[1]=t("p",null,"This journey keeps a trace of what the session brought, so the next one starts from there. It has two modes: an update of the context while you work, and a full archive at the end of the session.",-1)),e[2]||(e[2]=t("p",null,[t("strong",null,"Archiving is never automatic."),o(" Kessho does not archive anything by itself: an archive happens when the agent calls the tool, because you ask for it or because it judges it useful and necessary. What an agent decides to do on its own depends on its capabilities and on the instructions it follows (the procedure shipped with Kessho, your project's instructions): some archive on their own initiative, others wait for you to ask.")],-1)),e[3]||(e[3]=t("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[o("What you ask the agent "),t("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),e[4]||(e[4]=t("p",null,"You can ask for the context to be updated at any time. Depending on its capabilities and instructions, the agent may also do it on its own when it judges that a fact, a decision or a next step is worth keeping; no Kessho rule obliges it to. To trigger it yourself:",-1)),s(r,{tool:"mem_archive"}),s(a,{say:"Set this summary on kessho-docs: “Bilingual Kessho documentation, MCP reference derived from the catalog.”",verb:"mem_set_summary",family:"session",args:'{"slug":"kessho-docs","summary":"Bilingual Kessho documentation, MCP reference derived from the catalog."}'}),e[5]||(e[5]=t("p",null,[o(`At the end of the session, it is up to you to ask for the full archive ("we're stopping", "I'm done", or `),t("code",null,"/mem-archive"),o(" in Claude Code); an agent may also suggest it or run it on its own if it judges the session rich enough:")],-1)),s(a,{say:"We're stopping here: archive the kessho-docs session. It settled the outline of the “With an agent” section; also keep the principle “only document what the code supports”.",verb:"mem_archive",family:"session",args:'{"slug":"kessho-docs","mode":"full","archive_subject":"Outline of the With an agent section","archive_body_md":"Outline settled: seven journeys, one check on the tools cited.","context_md":"## Where the project stands\\n\\nThe “With an agent” section is being written.\\n\\n## Next steps\\n\\n1. Proofread the seven journeys.","derive":[{"fact":"Only document what the code supports","body":"A claim the catalog does not support has no place in the section.","kind":"principle"}]}'}),s(a,{say:"Cancel the last archive of kessho-docs, I picked the wrong project.",verb:"mem_rollback_archive",family:"session",args:'{"slug":"kessho-docs"}'}),e[6]||(e[6]=i('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="during-the-session-incremental-mode" tabindex="-1">During the session: incremental mode <a class="header-anchor" href="#during-the-session-incremental-mode" aria-label="Permalink to &quot;During the session: incremental mode&quot;">​</a></h3><p><a href="/Kessho/en/reference/mcp/session.html#mem-archive"><code>mem_archive</code></a> without <code>mode</code> (or with <code>mode: &quot;incremental&quot;</code>) rewrites <strong>only</strong> the project&#39;s <code>context.md</code>. No archive is created, no line is added to the history.</p><ul><li><code>slug</code> is the only required parameter.</li><li><code>context_md</code> is the <strong>whole new body</strong>: it replaces the current one. To keep it as is (for instance to set only a phase), the agent <strong>omits</strong> the field. An empty string is refused, nothing is written.</li><li><code>phase</code> sets the phase, only if provided. <a href="/Kessho/en/reference/mcp/session.html#mem-update-phase"><code>mem_update_phase</code></a> does the same alone, preserving the body word for word; an empty string clears the phase.</li><li><code>expect_decisions</code> lists decisions that must <strong>survive</strong> in the new body: if they are gone, the call is refused.</li><li>A <code>[[…]]</code> link in the body that leads to no note is refused: the agent fixes or removes the link.</li></ul><p>Refusals come <strong>before</strong> the first write: a refusal never leaves anything half done.</p><h3 id="at-the-end-of-the-session-full-mode" tabindex="-1">At the end of the session: full mode <a class="header-anchor" href="#at-the-end-of-the-session-full-mode" aria-label="Permalink to &quot;At the end of the session: full mode&quot;">​</a></h3><p><code>mode: &quot;full&quot;</code> does three things: it creates a timestamped archive in the project&#39;s <code>archives/</code>, it adds its line at the top of <code>history.md</code>, and it rewrites <code>context.md</code>. It requires:</p><ul><li><code>archive_subject</code> (the short subject) and <code>archive_body_md</code> (the archive body);</li><li><strong>what the session leaves that lasts, or why it leaves nothing.</strong> Either <code>derived_atoms</code> (links to notes that already exist), or <code>derive</code>, or <code>no_derived_because</code> (the reason). The server refuses <strong>silence</strong>: an archive that says neither is not written. A plain &quot;nothing lasting tonight&quot; is enough for <code>no_derived_because</code>, but an empty string is not. The idea is that a fact left inside an archive is harder to find again than a note of its own.</li></ul><p><code>derive</code> is the shortcut: a list of facts (<code>fact</code>, <code>body</code>, <code>kind</code> among <code>principle</code>, <code>goal</code>, <code>knowledge</code>) that the tool itself writes as notes in their zone, with a link back to the session. If one of the names is already taken, the <strong>whole</strong> archive is refused: no note is overwritten, no suffix is added.</p><p>Options: <code>archive_aliases</code> (the everyday words by which this archive will be searched later, which helps it surface in <a href="/Kessho/en/reference/mcp/rappel.html#mem-search"><code>mem_search</code></a>) and <code>archive_extra_fm</code> (extra frontmatter: <code>tags</code> lists are merged, other keys are replaced).</p><p><code>[[…]]</code> links are checked as in incremental mode, in both bodies (those of the notes <code>derive</code> is about to create count as existing). The project must be active: an archived project is refused (see <a href="/Kessho/en/agent/reprendre.html">Resume a project</a>).</p><h3 id="after-the-archive" tabindex="-1">After the archive <a class="header-anchor" href="#after-the-archive" aria-label="Permalink to &quot;After the archive&quot;">​</a></h3><ul><li><a href="/Kessho/en/reference/mcp/session.html#mem-set-summary"><code>mem_set_summary</code></a> sets the project&#39;s short summary, 300 characters at most, in the frontmatter of <code>context.md</code>. The catalog asks for it to be called after every archive: the summary is written by the agent, the vault cannot guess it.</li><li>If the memory is a git repository and the <strong>Automation</strong> box (&quot;Agents commit and sync automatically&quot;, in <strong>Settings › Sync</strong>) is ticked, Kessho&#39;s automation commits and pushes what the tool has just written, and the procedure has the agent call <a href="/Kessho/en/reference/mcp/git.html#mem-git-sync"><code>mem_git_sync</code></a> at the end of the session. See <a href="/Kessho/en/agent/synchroniser.html">Sync the memory</a>.</li></ul><h3 id="cancel-the-last-archive" tabindex="-1">Cancel the last archive <a class="header-anchor" href="#cancel-the-last-archive" aria-label="Permalink to &quot;Cancel the last archive&quot;">​</a></h3><p><a href="/Kessho/en/reference/mcp/session.html#mem-rollback-archive"><code>mem_rollback_archive</code></a> (<code>slug</code>) <strong>deletes</strong> the project&#39;s last archive and removes its line from <code>history.md</code>. Two limits, stated by the catalog and by the code:</p><ul><li><code>context.md</code> is <strong>not restored</strong>: it keeps the body the archive had written.</li><li>the notes written by <code>derive</code> are not removed: the tool only touches the archive and the history.</li></ul><p><strong>The tool has no guard</strong>: no <code>confirm</code>, it deletes as soon as it is called. The agent should ask you to confirm before calling it.</p><p>The deleted archive does not go to a trash: only git history, if it had been committed, keeps it.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2>',19)),s(h,{name:"fraicheur",alt:"The freshness indicator, top right: an agent has just written, the indicator lights up and says which zone moved."}),e[7]||(e[7]=i('<p>When the agent writes, the <strong>freshness indicator</strong> (the dot at the top right) lights up. Its panel says how long ago and which zone moved; <strong>Reload</strong> refreshes the screen (see <a href="/Kessho/en/guide/zones.html">Zones</a>).</p><p>An archive appears in the <strong>Sessions</strong> zone, under its project; the context is the one the <strong>Context keys</strong> screen reads, with the number of archives and the date of the last session (see <a href="/Kessho/en/guide/home.html">Home</a>). The <strong>GIT</strong> field of the status bar says where the commits stand (see <a href="/Kessho/en/guide/sync.html">Sync</a>).</p>',2))])}const _=d(m,[["render",u]]);export{w as __pageData,_ as default};
